INSERT INTO `goods` VALUES (1,'Hello Kitty 经典公仔 30cm','🧸','公仔',89.00,'超柔软的Hello Kitty经典款公仔，30cm高，短绒面料亲肤不起球，内充PP棉回弹饱满不易塌。抱着睡觉刚刚好，也是送闺蜜的生日礼物首选，粉丝必入款～','2026-10-28 08:57:01'),(2,'草莓弹簧发卡','🍓','配饰',12.50,'粉嫩草莓造型发卡，弹簧夹设计抓力适中不夹头发。树脂材质打磨圆润不刮头皮，日常通勤、约会、拍照都能戴，一夹就能提升整体甜度。','2026-10-28 08:57:01'),(3,'粉色磨砂笔记本 A5','📒','文具',25.00,'A5横线内页，80g加厚纸张中性笔不洇墨不透页。粉色磨砂封面手感细腻，附赠Hello Kitty贴纸一版可自己DIY封面，上课记笔记、写手账都超有动力。','2026-10-28 08:57:01'),(4,'猫咪造型抱枕 45cm','🐱','家居',69.00,'45cm大号猫咪抱枕，填充饱满有弹性，靠在沙发上看剧必备。水晶超柔面料摸起来像撸真猫，可拆洗设计方便打理，午睡垫腰一物多用。','2026-10-28 08:57:01'),(5,'樱花渐变保温杯 500ml','🥤','生活',45.00,'500ml樱花渐变保温杯，316不锈钢内胆，保冷保温12小时。杯盖带提绳方便携带，双重密封圈防漏，丢包里也不怕，冬天喝到一口热水真的会幸福。','2026-10-28 08:57:01'),(6,'草莓奶油切块蛋糕','🍰','美食',39.90,'草莓奶油切块蛋糕，动物奶油不腻口，蛋糕胚松软带淡淡奶香，夹层是整颗草莓果肉。下午茶配一杯红茶刚刚好，冷藏后口感更佳，当天食用风味最佳。','2026-10-28 08:57:01'),(7,'冬季毛绒居家拖鞋','🥿','家居',29.00,'冬季加厚毛绒居家拖鞋，防滑软底踩上去像踩在云朵上。内里长绒保暖，包裹感十足，冬天起床第一件事不再是\"脚冷警告\"，36-40码可选。','2026-10-28 08:57:01'),(8,'镀金星星发夹五件套','⭐','配饰',9.90,'镀金星星小发夹，一套5只装，大中小三种尺寸随心组合。碎发神器，怎么夹都好看，合金电镀工艺久戴不易褪色，学生党人手一套的性价比之王。','2026-10-28 08:57:01'),(9,'云朵造型触控台灯','💡','家居',99.00,'云朵造型小夜灯，三档调光（暖光/自然光/柔光），轻触即可开关。内置1800mAh电池满电续航8小时，放床头、书桌都治愈感拉满，也是拍照氛围道具。','2026-10-28 08:57:01'),(10,'爱心信封信纸套装','💌','文具',6.00,'粉色爱心信封+信纸一套10张，信纸带淡淡樱花暗纹，书写顺滑。写给朋友的一封信，从选纸到落笔都仪式感满满，比微信消息温度高多了。','2026-10-28 08:57:01'),(11,'Hello Kitty 大号抱枕公仔 50cm','🐼','公仔',159.00,'50cm大号设计，从床头装饰到沙发靠垫一物两用。莫兰迪粉配奶白蝴蝶结，颜色温柔不甜腻，外套可拆洗，脏了也不用担心。','2026-11-09 10:59:58'),(12,'迷你 Kitty 挂件公仔','🎀','公仔',29.90,'巴掌大小的迷你挂件公仔，8cm精致尺寸，金属挂扣可挂在书包、钥匙串、手机链上。一套三只不同表情，走到哪带到哪，回头率超高。','2026-11-09 10:59:58'),(13,'Kitty & Dear Daniel 情侣公仔','💕','公仔',128.00,'Kitty和Dear Daniel的CP组合装，一粉一蓝成对出现，五官精致刺绣做工。附赠爱心礼盒包装，纪念日、情人节送礼直接拿捏，拆开就是双倍甜蜜。','2026-11-09 10:59:58'),(14,'Hello Kitty 珍珠项链','📿','配饰',69.00,'淡水小珍珠串链，中间坠一枚Kitty头像金属吊牌，甜美里带一点轻优雅。锁扣采用龙虾扣，佩戴牢固不易掉，通勤约会两相宜，拍照格外上镜。','2026-11-09 10:59:58'),(15,'Kitty 猫耳发箍','🐱','配饰',25.00,'毛绒猫耳发箍，耳朵内置软钢丝可自由掰出造型。内圈全包布不硌头，戴一整天也不勒，漫展、生日会、日常卖萌三合一必备单品。','2026-11-09 10:59:58'),(16,'草莓牛奶瓶耳钉一对','🥛','配饰',19.90,'草莓牛奶瓶造型小耳钉，925银针不过敏，耳垂敏感星人也能放心戴。3D立体小造型，日常佩戴刚刚好，摘戴方便，通勤也不会太夸张。','2026-11-09 10:59:58'),(17,'Kitty 造型中性笔三支装','🖊️','文具',15.90,'笔帽是Kitty头的可爱中性笔，0.5mm黑色笔芯书写流畅不断墨，一支能写很久。三支装轮流换着用，放在笔袋里每次拿笔都有好心情。','2026-11-09 10:59:58'),(18,'草莓便签砖 300张','📝','文具',12.00,'草莓造型的便签砖，一砖300张超耐用，纸张带微黏性可随手贴在电脑边、书页上。记TODO、划重点、给同事留小纸条，办公学习桌面的颜值担当。','2026-11-09 10:59:58'),(19,'樱花粉荧光笔六色套装','🖍️','文具',22.00,'六色柔和荧光笔，划重点不刺眼、不透纸，双头笔尖粗细两用。马卡龙配色看着就心情好，备考划重点神器，笔记颜值直接拉满。','2026-11-09 10:59:58'),(20,'Kitty 咖啡对杯','☕','家居',59.00,'情侣对杯设计，一只Kitty一只蝴蝶结，釉下彩工艺安全无毒可进微波炉。350ml容量刚好一杯拿铁，早上和喜欢的人各端一只，仪式感从早餐开始。','2026-11-09 10:59:58'),(21,'粉色加绒毛毯 100×150cm','🛏️','家居',79.00,'法兰绒加厚毛毯，100×150cm午睡刚刚好，不掉毛不起静电。办公室午休盖、沙发上追剧盖、车里备一条都可以，可机洗，越洗越软。','2026-11-09 10:59:58'),(22,'Kitty 猫爪印马克杯','🍵','生活',35.00,'杯底是粉粉猫爪印的马克杯，350ml容量，倒满热牛奶时爪印会慢慢显现，可爱到犯规。陶瓷材质厚实保温，配下午茶点心，出片率100%。','2026-11-09 10:59:58'),(23,'草莓香氛护手霜三支装','🧴','生活',39.90,'草莓奶油香氛护手霜三支装，包里、办公桌、床头各放一支随时补涂。质地清爽不粘腻、吸收快，秋冬干燥救星，甜甜的草莓味能留一上午。','2026-11-09 10:59:58'),(24,'Kitty 造型草莓大福','🍡','美食',26.00,'手工草莓大福，Q弹雪媚娘外皮包裹整颗新鲜草莓和红豆沙，Kitty小脸用可可粉手绘。冰过之后口感像冰淇淋，一颗一口，甜度刚刚好不齁。','2026-11-09 10:59:58'),(25,'Hello Kitty 连帽卫衣 粉','👕','服装',139.00,'oversize宽松版型连帽卫衣，胸前Kitty头像印花经过水洗工艺不掉色。内里加绒保暖，搭配牛仔裤半身裙都好看，秋季通勤上学必备。','2026-11-09 10:59:13'),(26,'蝴蝶结针织开衫','🧶','服装',129.00,'马卡龙粉针织开衫，领口手工缝制立体小蝴蝶结，珍珠扣点缀。纱线柔软不扎皮肤，空调房、初秋早晚披上刚刚好，甜美又百搭。','2026-11-09 10:59:13'),(27,'粉色百褶半身长裙','👗','服装',99.00,'高腰百褶长裙，裙摆随步伐层层散开自带氛围感。内衬不透光，垂感好不易皱，配卫衣、开衫都能穿出温柔学院风，拍照超出片。','2026-11-09 10:59:13'),(28,'奶油色直筒休闲裤','👖','服装',109.00,'直筒微阔版型显腿直，腰头抽绳松紧腰不勒肚子。垂坠感面料抗皱免烫，通勤上课坐一天也不闷，奶油白四季都能搭。','2026-11-09 10:59:13'),(29,'Kitty 刺绣毛呢外套','🧥','服装',259.00,'双面羊毛混纺毛呢外套，版型挺括不塌肩，袖口绣有小Kitty头像。配裙子是优雅淑女，配裤子是利落通勤，一件穿出两种风格。','2026-11-09 10:59:13'),(30,'加厚连帽毛绒棉袄','🧣','服装',329.00,'冬季加厚棉服，外层防风面料内里摇粒绒，帽檐缀有一对Kitty猫耳。锁温不臃肿，零下出门也不怕，可爱和保暖我全都要。','2026-11-09 10:59:13'),(31,'蝴蝶结系带帆布鞋','👟','鞋子',89.00,'经典小白鞋底+粉色帆布鞋面，鞋帮两侧蝴蝶结设计甜美加分。橡胶大底防滑耐磨，鞋垫加软踩起来像踩棉花，逛街一天不累脚。','2026-11-09 10:59:13'),(32,'草莓厚底松糕运动鞋','🥾','鞋子',159.00,'4.5cm厚底增高不累脚，鞋侧草莓刺绣小巧思。网面透气不闷脚，轻量化设计单只不到250g，跑步通勤两相宜。','2026-11-09 10:59:13'),(33,'毛绒保暖雪地靴','🧦','鞋子',189.00,'加厚羊毛内里雪地靴，鞋口一圈绒毛自带可爱属性。防滑大底踩雪不滑，零下十度出门脚丫也是暖的，冬季衣柜定番单品。','2026-11-09 10:59:13'),(34,'Kitty 头小方包单肩包','👛','包包',119.00,'三档可调节肩带，手提单肩斜挎三种背法。Kitty头像立体浮雕包扣，PU皮面防泼水好打理，手机钱包口红统统装得下。','2026-11-09 10:59:13'),(35,'珍珠链条小圆包','👝','包包',99.00,'云朵粉小圆包，金属链条上串着小珍珠，赴约拍照的点睛单品。磁扣开合单手就能操作，装个手机口红补妆镜刚刚好。','2026-11-09 10:59:13'),(36,'Kitty 大容量托特包','👜','包包',149.00,'能装下14寸电脑的大容量托特包，内设分层口袋，水杯、雨伞、iPad各归其位。帆布面料结实耐造，上课通勤旅游一包搞定。','2026-11-09 10:59:13'),(37,'樱花粉晶锁骨项链','🌸','配饰',79.00,'粉水晶樱花吊坠锁骨链，链身S925银不过敏。光线下一闪一闪的超显肤色，配V领和衬衫都好看，日常通勤也能戴的轻珠宝。','2026-11-09 10:59:13'),(38,'Kitty 头珍珠耳钉一对','💍','配饰',49.90,'Kitty小脸配天然小珍珠的耳钉，925银针敏感耳也能戴。微微垂坠的款式显脸小，约会、上班、拍照随时切换氛围。','2026-11-09 10:59:13'),(39,'蝴蝶结丝绒choker','🎀','配饰',35.00,'丝绒质地颈链，正中一颗立体小蝴蝶结，后段弹力绳可调节松紧。不勒脖子不起球，搭配裙子瞬间提气，漫展拍照神器。','2026-11-09 10:59:13'),(40,'Kitty 吸管水杯 650ml','🥛','生活',39.90,'带吸管的随手杯，PPSU杯身耐摔不怕摔，吸管口有防尘盖。上学、健身、办公室随手拎，喝水量翻倍的秘密武器。','2026-11-09 10:59:13'),(41,'樱花玻璃茶杯带滤网','🍵','生活',45.00,'高硼硅玻璃杯身配樱花粉滤网，泡茶泡花茶一目了然。把手握感舒适不烫手，下午茶摆在桌上就是一幅画。','2026-11-09 10:59:13'),(42,'Kitty 便携运动水壶','🚰','生活',55.00,'一键弹盖运动水壶，单手开合防漏不洒。Tritan材质无异味，700ml大容量带刻度，骑行、跑步、瑜伽后一口冰水超满足。','2026-11-09 10:59:13'),(43,'粉色气垫按摩梳','💄','美妆',29.90,'气囊梳齿按摩头皮不拉扯打结，梳完头发蓬松又顺滑。手柄圆润握感舒适，包里放一把随时整理刘海，颜值实力双在线。','2026-11-09 10:59:13'),(44,'草莓润唇膏 3.5g','🧴','美妆',19.90,'草莓味的滋润型润唇膏，睡前厚涂一层当唇膜，早起嘴唇水嫩不起皮。管身小巧随身带，秋冬干燥救星，涂完还有淡淡果香。','2026-11-09 10:59:13'),(45,'猫爪印花化妆镜','🪞','美妆',49.00,'双面化妆镜一面普通一面放大3倍，镜面带猫爪印花边框。底座稳不晃，放梳妆台每天化妆都是好心情，也是桌面颜值担当。','2026-11-09 10:59:13'),(46,'Kitty 无线鼠标 静音','🖱️','数码',69.00,'猫爪造型静音鼠标，点击几乎无声，办公室深夜用也不吵。2.4G即插即用，一节电池用半年，办公桌第一萌物。','2026-11-09 10:59:13'),(47,'Hello Kitty 手机壳','📱','数码',35.00,'全包防摔气囊手机壳，内衬绒布不刮机，Kitty印花不掉漆。镜头口加高保护摄像头，可爱和安全一个不落。','2026-11-09 10:59:13'),(48,'猫耳蓝牙耳机保护套','🎧','数码',25.00,'硅胶猫耳耳机套，自带挂绳防丢。手感软弹防尘防摔，耳机放进包里再也不怕刮花，挂在包上还是个可爱小挂件。','2026-11-09 10:59:13');
